package main

type Numeral struct {
    Value  int
    Symbol string
}

var numerals = []Numeral{
    {1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"},
    {100, "C"}, {90, "XC"}, {50, "L"}, {40, "XL"},
    {10, "X"}, {9, "IX"}, {5, "V"}, {4, "IV"}, {1, "I"},
}

func ToRoman(n int) string {
    if n <= 0 || n > 3999 {
        return ""
    }
    out := ""
    for _, numeral := range numerals {
        for n >= numeral.Value {
            out += numeral.Symbol
            n -= numeral.Value
        }
    }
    return out
}

func DigitSum(n int) int {
    total := 0
    for n > 0 {
        total += n % 10
        n /= 10
    }
    return total
}

