package main

func Sieve(limit int) []int {
    if limit < 2 {
        return nil
    }
    marks := make([]bool, limit+1)
    primes := make([]int, 0, limit/4)
    for n := 2; n <= limit; n++ {
        if marks[n] {
            continue
        }
        primes = append(primes, n)
        for multiple := n * n; multiple <= limit; multiple += n {
            marks[multiple] = true
        }
    }
    return primes
}

func DecadeCounts(primes []int) []int {
    counts := make([]int, 10)
    for _, p := range primes {
        decade := p / 10
        if decade > 9 {
            decade = 9
        }
        counts[decade]++
    }
    return counts
}

