package main

type Year struct {
    Value   int
    Leap    bool
    Days    int
    Weekday string
}

func IsLeap(year int) bool {
    if year%400 == 0 {
        return true
    }
    if year%100 == 0 {
        return false
    }
    return year%4 == 0
}

func DaysIn(year int, month int) int {
    switch month {
    case 2:
        if IsLeap(year) {
            return 29
        }
        return 28
    case 4, 6, 9, 11:
        return 30
    default:
        return 31
    }
}

func Zeller(year int, month int, day int) int {
    y := year
    m := month
    if m < 3 {
        m += 12
        y--
    }
    k := y % 100
    j := y / 100
    h := (day + (13*(m+1))/5 + k + k/4 + j/4 + 5*j) % 7
    return h
}

func WeekdayName(h int) string {
    names := []string{"Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"}
    if h < 0 || h >= len(names) {
        return "?"
    }
    return names[h]
}

func Summaries(years []int) []Year {
    out := make([]Year, 0, len(years))
    for _, year := range years {
        if year < 1 {
            continue
        }
        days := 0
        for month := 1; month <= 12; month++ {
            days += DaysIn(year, month)
        }
        weekday := WeekdayName(Zeller(year, 1, 1))
        out = append(out, Year{Value: year, Leap: IsLeap(year), Days: days, Weekday: weekday})
    }
    return out
}

