package main

import (
    "fmt"
    "strings"
)

func MorseReport(phrases []string) string {
    var b strings.Builder
    for _, phrase := range phrases {
        code := Encode(phrase)
        status := "mismatch"
        if RoundTrip(phrase) {
            status = "ok"
        }
        if code == "" {
            code = "-"
        }
        b.WriteString(fmt.Sprintf("%-8q %-26s %s\n", phrase, code, status))
    }
    b.WriteString(fmt.Sprintf("%d phrases\n", len(phrases)))
    return b.String()
}

