  const rows = [];
  let total = 0;
  for (let i = 0; i < bookings.length; i += 1) {
    const booking = bookings[i];
    const unit = PRICES[booking.zone];
    let discount = 0;
    if (booking.group === 'students') {
      discount = 0.25;
    } else if (booking.group === 'members') {
      discount = 0.1;
    }
    if (booking.qty >= 4) {
      discount = discount + 0.05;
