    const gross = unit * booking.qty;
    const net = Math.round(gross * (1 - discount));
    total += net;
    rows.push({
      group: booking.group,
      zone: booking.zone,
      qty: booking.qty,
      discount: discount,
      net: net
    });
  }
  return { rows: rows, total: total };
}

function busiest(rows) {
  let best = rows[0];
  for (let i = 1; i < rows.length; i += 1) {
    if (rows[i].net > best.net) {
      best = rows[i];
    }
  }
  return best.zone;
}

module.exports = {
  BOOKINGS: BOOKINGS,
  priceBookings: priceBookings,
  busiest: busiest
};

