const TEXT =
  'A small report generator wraps a paragraph to a fixed width and prints ' +
  'a ruler above it so the wrap can be checked by eye without counting ' +
  'characters by hand';

function wrap(text, width) {
  const words = text.split(' ');
  const lines = [];
  let line = '';
  for (let i = 0; i < words.length; i += 1) {
    const word = words[i];
    if (word.length === 0) {
      continue;
    }
    if (line.length === 0) {
      line = word;
    } else if (line.length + 1 + word.length <= width) {
      line = line + ' ' + word;
    } else {
      lines.push(line);
      line = word;
    }
  }
  if (line.length > 0) {
    lines.push(line);
  }
  return lines;
}

function widest(lines) {
  let width = 0;
  for (let i = 0; i < lines.length; i += 1) {
    if (lines[i].length > width) {
      width = lines[i].length;
    }
  }
  return width;
}

module.exports = { TEXT: TEXT, wrap: wrap, widest: widest };

