           66, 70, 74, 79, 83, 88, 92, 97]
WIDTH = 10


def bucket_of(value, width):
    if value < 0:
        return -1
    return value // width


def summarise(samples, width):
    counts = {}
    total = 0
    peak = 0
    peak_bucket = 0
    for value in samples:
        total = total + value
        key = bucket_of(value, width)
        if key in counts:
            counts[key] = counts[key] + 1
        else:
            counts[key] = 1
        if counts[key] > peak:
            peak = counts[key]
            peak_bucket = key
    mean = total // len(samples) if samples else 0
