# Card numbers and the digit the Luhn rule says they should end with.

NUMBERS = [
    "4539578763621486",
    "6011111111111117",
    "79927398713",
    "79927398710",
    "4222222222222",
]


def digits_of(text):
    out = []
    for ch in text:
        if ch.isdigit():
            out.append(int(ch))
    return out


def describe(number):
    digits = digits_of(number)
    if not digits:
        return "empty", 0
    total = 0
    doubled = 0
    for position, digit in enumerate(reversed(digits)):
        if position % 2 == 1:
            value = digit * 2
            if value > 9:
                value = value - 9
            doubled = doubled + 1
            total = total + value
        else:
            total = total + digit
    if len(digits) < 2:
        return "short", total
    if total % 10 == 0:
        return "ok", total
    return "invalid", total


def summarise(numbers):
    rows = []
    ok = 0
    longest = 0
    for number in numbers:
        status, total = describe(number)
        if status == "ok":
            ok = ok + 1
        if len(number) > longest:
            longest = len(number)
        rows.append((number, total, total % 10, status))
    return {"rows": rows, "ok": ok, "longest": longest,
            "count": len(numbers)}

